'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['renderTemplate']);
assert.strictEqual(typeof api.renderTemplate, 'function');
const { renderTemplate } = api;

assert.strictEqual(renderTemplate('', {}), '');
assert.strictEqual(
  renderTemplate('Hello {{name}}; {{name}} has {{count_2}}.', { name: 'Ada', count_2: 'three' }),
  'Hello Ada; Ada has three.'
);
assert.strictEqual(
  renderTemplate('{{a}}{{b}}{{a}}', { a: '{{b}}', b: 'X' }),
  '{{b}}X{{b}}'
);
assert.strictEqual(
  renderTemplate('{{ valid }} {{9bad}} {{bad-key}} {{} } {{{ok}}}', { ok: 'Y' }),
  '{{ valid }} {{9bad}} {{bad-key}} {{} } {Y}'
);

const values = { first: 'one', unused: 'two' };
const before = { ...values };
assert.strictEqual(renderTemplate('{{first}}', values), 'one');
assert.deepStrictEqual(values, before);

const inherited = Object.create({ hidden: 'inherited' });
inherited.own = 'visible';
assert.strictEqual(renderTemplate('{{own}}', inherited), 'visible');
assert.throws(() => renderTemplate('{{hidden}}', inherited), RangeError);
assert.throws(() => renderTemplate('{{missing}} and {{present}}', { present: 'yes' }), RangeError);

for (const args of [
  [null, {}],
  [12, {}],
  ['x', null],
  ['x', []],
  ['x', 'object'],
  ['x', { 'bad-key': 'value' }],
  ['x', { '9bad': 'value' }],
  ['x', { good: 1 }],
  ['', { used: 'ok', invalid: false }]
]) {
  assert.throws(() => renderTemplate(args[0], args[1]), TypeError);
}

